typedef struct Ucf084NanaDashbackInput {
    u8 x0[6];
    u8 main_stick_x;
    u8 x7[0x18 - 7];
    float facing_dir;
} Ucf084NanaDashbackInput;

static void ucf084_apply_dashback(Fighter* fp)
{
    int raw_delta;

    if (fp->x221F_b4 || fp->cur_anim_frame != 2.0F ||
        fp->facing_dir * fp->input.lstick[0].x <
            p_ftCommonData->dash_smash_stick_threshold ||
        fp->x670_timer_lstick_tilt_x > 1)
    {
        return;
    }

    raw_delta = pf_ssbm_native_ucf084_raw_main_x_delta_two_frames(
        fp->x618_player_id);
    if (raw_delta * raw_delta <= 75 * 75) {
        return;
    }

    fp->mv.co.turn.has_turned = true;
    fp->mv.co.turn.just_turned = true;
    {
        Fighter_GObj* partner_gobj =
            Player_GetEntityAtIndex(fp->player_id, 1);
        if (partner_gobj != NULL) {
            Fighter* partner_fp = GET_FIGHTER(partner_gobj);
            Ucf084NanaDashbackInput* partner_input =
                (Ucf084NanaDashbackInput*) partner_fp->cpu.x444;
            union {
                float value;
                u32 bits;
            } facing;
            facing.value = fp->facing_dir;
            partner_input->facing_dir = fp->facing_dir;
            partner_input->main_stick_x =
                (u8) ((facing.bits >> 31) + 0x7F);
        }
    }
}

